--
-- Table structure for table `project`
--

DROP TABLE IF EXISTS `project`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `project` (
  `project_id` int NOT NULL AUTO_INCREMENT,
  `project_category_id` int NOT NULL,
  `project_manager_id` int NOT NULL,
  `asst_project_manager_id` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `project_qa_id` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `project_team_id` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `project_name` text COLLATE utf8mb4_general_ci NOT NULL,
  `project_code` text COLLATE utf8mb4_general_ci NOT NULL,
  `project_description` text COLLATE utf8mb4_general_ci,
  `is_active` int NOT NULL DEFAULT '1',
  `project_pprt` longtext COLLATE utf8mb4_general_ci,
  `project_pprt_base64` text COLLATE utf8mb4_general_ci,
  `created_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `ai_evaluation` tinyint NOT NULL DEFAULT '0',
  `duplicate_check` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`project_id`),
  CONSTRAINT `project_chk_1` CHECK (json_valid(`project_qa_id`)),
  CONSTRAINT `project_chk_2` CHECK (json_valid(`project_team_id`))
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

