DROP TABLE IF EXISTS `qc_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `qc_records` (
  `id` int NOT NULL AUTO_INCREMENT,
  `assistant_manager_id` int DEFAULT NULL,
  `qa_user_id` int DEFAULT NULL,
  `agent_id` int DEFAULT NULL,
  `project_id` int DEFAULT NULL,
  `task_id` int DEFAULT NULL,
  `tracker_id` int NOT NULL,
  `whole_file_path` varchar(255) DEFAULT NULL,
  `qc_file_path` varchar(255) DEFAULT NULL,
  `date_of_file_submission` datetime DEFAULT NULL,
  `qc_score` double(5,2) DEFAULT NULL,
  `status` enum('regular','correction','rework') DEFAULT NULL,
  `qc_status` varchar(50) DEFAULT NULL,
  `file_record_count` int DEFAULT NULL,
  `qc_generated_count` int DEFAULT NULL,
  `error_list` longtext,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=143 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

