DROP TABLE IF EXISTS `qc_rework_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `qc_rework_history` (
  `qc_rework_id` int NOT NULL AUTO_INCREMENT,
  `qc_record_id` int NOT NULL,
  `qc_file_path` varchar(255) DEFAULT NULL,
  `rework_file_path` varchar(255) DEFAULT NULL,
  `rework_sample_file` varchar(500) DEFAULT NULL COMMENT 'Sample file QA generated to fail this rework cycle',
  `rework_file_qc_status` varchar(20) DEFAULT NULL,
  `rework_count` int DEFAULT '0',
  `rework_status` enum('rework','completed') DEFAULT 'rework',
  `rework_qc_score` double DEFAULT NULL,
  `rework_error_list` longtext,
  `file_record_count` int DEFAULT NULL,
  `qc_data_generated_count` int DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`qc_rework_id`),
  KEY `qc_record_id` (`qc_record_id`),
  CONSTRAINT `qc_rework_history_ibfk_1` FOREIGN KEY (`qc_record_id`) REFERENCES `qc_records` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

