DROP TABLE IF EXISTS `task`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `task` (
  `task_id` int NOT NULL AUTO_INCREMENT,
  `project_id` int NOT NULL,
  `task_team_id` text COLLATE utf8mb4_general_ci NOT NULL,
  `task_name` text COLLATE utf8mb4_general_ci NOT NULL,
  `task_description` text COLLATE utf8mb4_general_ci NOT NULL,
  `task_target` int NOT NULL,
  `task_file` longtext COLLATE utf8mb4_general_ci,
  `task_file_base64` longtext COLLATE utf8mb4_general_ci,
  `important_columns` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `qc_percentage` int NOT NULL,
  `is_active` int NOT NULL DEFAULT '1',
  `created_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`task_id`)
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
