DROP TABLE IF EXISTS `task_work_tracker`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `task_work_tracker` (
  `tracker_id` int NOT NULL AUTO_INCREMENT,
  `project_id` int NOT NULL,
  `task_id` int NOT NULL,
  `user_id` int NOT NULL,
  `date_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `production` double(11,2) NOT NULL,
  `tenure_target` text COLLATE utf8mb4_general_ci NOT NULL,
  `actual_target` text COLLATE utf8mb4_general_ci NOT NULL,
  `billable_hours` text COLLATE utf8mb4_general_ci NOT NULL,
  `actual_billable_hours` text COLLATE utf8mb4_general_ci,
  `tracker_file` longtext COLLATE utf8mb4_general_ci,
  `tracker_note` longtext COLLATE utf8mb4_general_ci,
  `shift` enum('DAY','NIGHT') COLLATE utf8mb4_general_ci DEFAULT 'DAY',
  `qc_status` int NOT NULL DEFAULT '0',
  `is_active` int NOT NULL,
  `updated_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`tracker_id`)
) ENGINE=InnoDB AUTO_INCREMENT=10295 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
