DROP TABLE IF EXISTS `tfs_user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tfs_user` (
  `user_id` int NOT NULL AUTO_INCREMENT,
  `project_manager_id` text COLLATE utf8mb4_general_ci,
  `asst_manager_id` text COLLATE utf8mb4_general_ci,
  `qa_id` text COLLATE utf8mb4_general_ci,
  `team_id` int NOT NULL,
  `role_id` int NOT NULL,
  `user_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `profile_picture` longtext COLLATE utf8mb4_general_ci,
  `profile_picture_base64` longtext COLLATE utf8mb4_general_ci,
  `user_number` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `user_address` text COLLATE utf8mb4_general_ci,
  `user_email` varchar(150) COLLATE utf8mb4_general_ci NOT NULL,
  `user_password` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `gemini_api_key` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_active` int NOT NULL DEFAULT '1',
  `is_delete` int NOT NULL DEFAULT '1',
  `designation_id` int DEFAULT NULL,
  `user_tenure` text COLLATE utf8mb4_general_ci,
  `device_type` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `device_id` text COLLATE utf8mb4_general_ci,
  `created_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deactivated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=166 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
