--
-- Table structure for table `tracker_records`
--

DROP TABLE IF EXISTS `tracker_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tracker_records` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `project_id` int NOT NULL,
  `task_id` int NOT NULL,
  `record_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `hash_value` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `status` varchar(50) COLLATE utf8mb4_general_ci DEFAULT 'processing',
  `file_path` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_hash_per_task` (`task_id`,`hash_value`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_project_id` (`project_id`),
  KEY `idx_task_id` (`task_id`),
  KEY `idx_hash_value` (`hash_value`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_tracker_records_hash_task` (`hash_value`,`task_id`),
  KEY `idx_tracker_records_task_id` (`task_id`),
  KEY `idx_tracker_records_user_task` (`user_id`,`task_id`),
  CONSTRAINT `tracker_records_chk_1` CHECK (json_valid(`record_data`))
) ENGINE=InnoDB AUTO_INCREMENT=55818 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

